        work[env_idx + 294] = work[env_idx + 294] + work[env_idx + 5];
        work[env_idx + 287] = work[env_idx + 287] * work[env_idx + 174];
        work[env_idx + 290] = work[env_idx + 290] * work[env_idx + 7];
        work[env_idx + 287] = work[env_idx + 287] - work[env_idx + 290];
        work[env_idx + 294] = work[env_idx + 294] + work[env_idx + 287];
        outputs[1][idx * nnz_out[1] + 2] = work[env_idx + 294];
    }
}


extern "C" {

void evaluate(const float *inputs[],
            float *work,
            float *outputs[],
            const int batch_size) {
    int blockSize = 256;
    int gridSize = (batch_size + blockSize - 1) / blockSize;
    evaluate_kernel<<<gridSize, blockSize>>>(inputs,
                                            work,
                                            outputs,
                                            batch_size);

    gpuErrchk(cudaPeekAtLastError());
    gpuErrchk(cudaDeviceSynchronize());
}

}